// Ürün sayfasının saf mantığı: tükenme, tutar (kuruş tamsayısıyla), yorum dağılımı ve yazımlar. Para TRY'dir.
import { exactText, averageText, countText, lineMinor, priceText, toMinor } from "../lib/shop-format";

export interface DetailPhoto { alt: string; src?: string | undefined; /** Fotoğrafın odak noktası (CSS object-position). */ position?: string | undefined; tone?: number | undefined }
export interface Finish { value: string; label: string; /** Örnek rengi (CSS rengi). */ color: string; photos: DetailPhoto[] }
export interface Size {
  value: string;
  label: string;
  /** Ana birimde TRY. */
  price: number;
  /** Bu boyun tükendiği kaplamalar (`Finish.value`). */
  soldOutIn?: string[] | undefined;
}
export interface Selection { finish: string; size: string; quantity: number }

export const isSoldOut = (size: Size, finish: string): boolean => !!size.soldOutIn?.includes(finish);

/** Kaplama değişince seçili boy o kaplamada tükenmişse seçim kalkar (boş metin). */
export function keepSize(sizes: Size[], size: string, finish: string): string {
  const found = sizes.find(item => item.value === size);
  return found && !isSoldOut(found, finish) ? size : "";
}

/** Satır tutarı kuruş tamsayısı: fiyat × adet. */
export const totalMinor = (price: number, quantity: number): number => lineMinor(toMinor(price), quantity);

/** Düğme etiketi: "Sepete ekle · ₺2.400,00". */
export const addLabel = (price: number, quantity: number): string => `Sepete ekle · ${exactText(totalMinor(price, quantity))}`;

/** `distribution[0]` 5 yıldızlı, `distribution[4]` 1 yıldızlı yorum sayısıdır. */
export type Distribution = [number, number, number, number, number];

export function reviewTotal(distribution: Distribution): number {
  return distribution.reduce((sum, count) => sum + count, 0);
}

/** Yıldız ortalaması; yorum yoksa null. */
export function reviewAverage(distribution: Distribution): number | null {
  const total = reviewTotal(distribution);
  if (!total) return null;
  return distribution.reduce((sum, count, at) => sum + count * (5 - at), 0) / total;
}

/** Çubuk oranı: en kalabalık satıra göre (0–1). */
export function barRatios(distribution: Distribution): number[] {
  const peak = Math.max(...distribution, 0);
  return distribution.map(count => peak ? count / peak : 0);
}

export const averageLabel = (distribution: Distribution): string => {
  const average = reviewAverage(distribution);
  return average === null ? "Henüz yorum yok" : `${averageText(average)} / 5`;
};
export const reviewCountText = (total: number): string => `${countText(total)} yorum`;
export const barRowLabel = (stars: number, count: number): string => `${stars} yıldız, ${reviewCountText(count)}`;
export const sizeLabel = (size: Size, soldOut: boolean): string => soldOut ? `${size.label} · ${priceText(size.price)} · Tükendi` : `${size.label} · ${priceText(size.price)}`;
export const counterText = (index: number, count: number): string => `${countText(index + 1)} / ${countText(count)}`;

.root { container-type: inline-size; display: grid; gap: var(--space-5); min-width: 0; color: var(--foreground); }
.layout { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: var(--space-8); align-items: start; }
.gallery { display: grid; gap: var(--space-3); position: sticky; top: var(--space-4); min-width: 0; }
.stage { position: relative; }
.photo { display: block; width: 100%; }
.counter { position: absolute; right: var(--space-3); bottom: var(--space-3); padding: 2px var(--space-2); border-radius: var(--radius-pill); background: color-mix(in oklch, var(--surface) 80%, transparent); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.arrow { position: absolute; top: 50%; width: 2.5rem; height: 2.5rem; margin-top: -1.25rem; border: 1px solid var(--border); border-radius: 50%; background: color-mix(in oklch, var(--surface) 85%, transparent); color: var(--foreground); font-size: var(--text-xl); line-height: 1; cursor: pointer; }
.arrow[data-side="prev"] { left: var(--space-3); } .arrow[data-side="next"] { right: var(--space-3); }
.arrow:disabled { opacity: .35; cursor: default; }
.arrow:focus-visible, .thumb:focus-visible, .heart:focus-visible, .sizeOption:focus-visible, .sectionButton:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 2px; }
@media (hover: none) { .arrow { display: none; } }
.thumbs { display: grid; grid-template-columns: repeat(auto-fit, minmax(3.5rem, 4.5rem)); gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.thumb { position: relative; display: block; width: 100%; padding: 0; border: 1px solid var(--border); border-radius: var(--radius-control); overflow: hidden; background: none; cursor: pointer; }
.thumb img { display: block; width: 100%; aspect-ratio: 1; object-fit: cover; }
.ring { position: absolute; inset: 0; border: 2px solid var(--foreground); border-radius: var(--radius-control); pointer-events: none; }
.info { display: grid; gap: var(--space-4); min-width: 0; }
.head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.name { margin: 0; font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; letter-spacing: var(--tracking-display); line-height: var(--leading-display); }
.heart { flex: none; display: grid; place-items: center; width: 2.5rem; height: 2.5rem; border: 1px solid var(--border); border-radius: 50%; background: var(--surface); color: var(--text-secondary); cursor: pointer; }
.heart[aria-pressed="true"] { color: var(--accent-strong); border-color: var(--accent); }
.price { margin: 0; font-size: var(--text-2xl); font-variant-numeric: tabular-nums; }
.muted { color: var(--text-muted); }
.ratingLine { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); }
.summary { margin: 0; padding-left: var(--space-5); color: var(--text-secondary); font-size: var(--text-sm); }
.group { display: grid; gap: var(--space-2); }
.groupLabel { margin: 0; color: var(--text-secondary); font-size: var(--text-xs); }
.groupLabel b { color: var(--foreground); font-weight: 500; }
.sizes { display: grid; grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); gap: var(--space-2); }
.sizeOption { min-height: 2.75rem; padding: var(--space-2) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font: inherit; font-size: var(--text-sm); text-align: left; cursor: pointer; }
.sizeOption[aria-checked="true"] { border-color: var(--foreground); box-shadow: inset 0 0 0 1px var(--foreground); }
.sizeOption[data-out] { color: var(--text-muted); }
.buy { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); }
.add { min-width: 15rem; }
.promises { display: grid; gap: var(--space-2); margin: 0; padding: var(--space-4) 0 0; border-top: 1px solid var(--border-subtle); list-style: none; font-size: var(--text-sm); }
.promises li { display: grid; gap: 2px; }
.promises span { color: var(--text-secondary); }
.reviews { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-5); align-items: center; padding: var(--space-4) 0; border-top: 1px solid var(--border-subtle); }
.average { display: grid; margin: 0; font-size: var(--text-sm); color: var(--text-secondary); }
.average b { color: var(--foreground); font-family: var(--font-display); font-size: var(--text-4xl); font-weight: 500; line-height: 1; }
.bars { display: grid; gap: 4px; margin: 0; padding: 0; list-style: none; font-size: var(--text-xs); color: var(--text-secondary); }
.bars li { display: grid; grid-template-columns: 1.5rem minmax(0, 1fr) 2rem; align-items: center; gap: var(--space-2); font-variant-numeric: tabular-nums; }
.bar { height: 6px; border-radius: 3px; background: var(--neutral-3); overflow: hidden; }
.bar i { display: block; height: 100%; border-radius: 3px; background: var(--foreground); transform-origin: left; }
.accordion { border-top: 1px solid var(--border-subtle); }
.section { border-bottom: 1px solid var(--border-subtle); }
.section h3 { margin: 0; }
.sectionButton { display: flex; width: 100%; align-items: center; justify-content: space-between; padding: var(--space-3) 0; border: 0; background: none; color: var(--foreground); font: inherit; font-size: var(--text-sm); font-weight: 500; text-align: left; cursor: pointer; }
.sectionBody { overflow: hidden; }
.sectionInner { padding: 0 0 var(--space-4); color: var(--text-secondary); font-size: var(--text-sm); }
.skeletonBlock { display: block; aspect-ratio: 1; border-radius: var(--radius-surface); background: var(--neutral-3); animation: pulse 1.4s ease-in-out infinite; }
.skeletonCol { display: grid; gap: var(--space-3); } .skeletonCol span { display: block; height: 1.2rem; border-radius: var(--radius-control); background: var(--neutral-3); animation: pulse 1.4s ease-in-out infinite; }
@keyframes pulse { 50% { opacity: .5; } }
.root[data-reduced] .skeletonBlock, .root[data-reduced] .skeletonCol span { animation: none; }
@media (prefers-reduced-motion: reduce) { .skeletonBlock, .skeletonCol span { animation: none; } }
@container (max-width: 980px) { .gallery { position: static; } }
@container (max-width: 680px) { .layout { grid-template-columns: minmax(0, 1fr); gap: var(--space-5); } .thumbs { grid-template-columns: repeat(4, minmax(0, 1fr)); } .add { min-width: 0; flex: 1; } }
@container (max-width: 420px) { .reviews { grid-template-columns: minmax(0, 1fr); } }

"use client";

import { useEffect, useId, useState, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Breadcrumb, type BreadcrumbItem } from "../breadcrumb/breadcrumb";
import { Button } from "../button/button";
import { motionTokens } from "../lib/motion-tokens";
import { FramedPhoto, NumberStepper, SwatchGroup, SwipeTrack, useAnnouncer } from "../lib/shop-parts";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { addLabel, barRatios, barRowLabel, counterText, isSoldOut, keepSize, reviewAverage, reviewCountText, reviewTotal, sizeLabel, type DetailPhoto, type Distribution, type Finish, type Selection, type Size } from "./product-detail-format";
import styles from "./product-detail.module.css";

export type { DetailPhoto, Distribution, Finish, Selection, Size };
export interface DetailSection { title: string; content: ReactNode }
export interface DetailPromise { title: string; text: string }

/** Tek bir ürünün sayfası için kullanın: kaydırılabilir galeri, kaplama ve boy seçimi, adet, sepete ekle, teslimat vaatleri, yorum özeti ve açılır ayrıntılar. Çok seçenekli canlı fiyatlı yapılandırıcı ve ürün listesi kapsam dışıdır; sepete ekleme ve haber verme kaydını uygulama bağlar. */
export interface ProductDetailProps {
  name: string;
  trail: BreadcrumbItem[];
  summary?: string[] | undefined;
  finishes: Finish[];
  sizes: Size[];
  /** 5'ten 1'e yıldız başına yorum sayısı. */
  reviews: Distribution;
  promises?: DetailPromise[] | undefined;
  sections?: DetailSection[] | undefined;
  maxQuantity?: number | undefined;
  /** Sepete ekler; reddederse düğme "Tekrar dene" der. */
  onAddToCart: (selection: Selection) => Promise<void>;
  /** Tükenen seçim için "Gelince haber ver". */
  onNotify?: ((selection: Selection) => void) | undefined;
  onFavoriteChange?: ((favorite: boolean) => void) | undefined;
  loading?: boolean | undefined;
}

function Gallery({ photos, name, finishKey }: { photos: DetailPhoto[]; name: string; finishKey: string }) {
  const reduced = useReducedMotionSafe();
  const [index, setIndex] = useState(0);
  useEffect(() => setIndex(0), [finishKey]);
  const safe = Math.min(index, Math.max(0, photos.length - 1));
  const slide = (at: number) => { const photo = photos[at]!; return <FramedPhoto src={photo.src} alt={photo.alt} ratio="1 / 1" position={photo.position} tone={photo.tone} eager={!at} className={styles.photo} />; };
  return <div className={styles.gallery}>
    <div className={styles.stage}>
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.div key={finishKey} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: reduced ? 0 : motionTokens.duration.standard }}>
          <SwipeTrack count={photos.length} index={safe} onIndexChange={setIndex} renderSlide={slide} label={`${name} fotoğrafları`} />
        </motion.div>
      </AnimatePresence>
      <span className={styles.counter} aria-live="polite">{counterText(safe, photos.length)}</span>
      {photos.length > 1 && <>
        <button type="button" className={styles.arrow} data-side="prev" aria-label="Önceki fotoğraf" disabled={safe === 0} onClick={() => setIndex(safe - 1)}>‹</button>
        <button type="button" className={styles.arrow} data-side="next" aria-label="Sonraki fotoğraf" disabled={safe === photos.length - 1} onClick={() => setIndex(safe + 1)}>›</button>
      </>}
    </div>
    <ul className={styles.thumbs}>{photos.map((photo, at) => <li key={at}><button type="button" className={styles.thumb} aria-label={`${at + 1}. fotoğrafı göster`} aria-current={at === safe || undefined} onClick={() => setIndex(at)}>
      <FramedPhoto src={photo.src} alt="" ratio="1 / 1" position={photo.position} tone={photo.tone} initial="" />
      {at === safe && <motion.span layoutId={`${finishKey}-ring`} className={styles.ring} transition={reduced ? { duration: 0 } : motionTokens.spring.snappy} />}
    </button></li>)}</ul>
  </div>;
}

function Accordion({ sections }: { sections: DetailSection[] }) {
  const uid = useId();
  const reduced = useReducedMotionSafe();
  const [open, setOpen] = useState(0);
  return <div className={styles.accordion}>{sections.map((section, at) => {
    const on = open === at;
    return <div key={section.title} className={styles.section}>
      <h3><button type="button" className={styles.sectionButton} aria-expanded={on} aria-controls={`${uid}-p${at}`} id={`${uid}-h${at}`} onClick={() => setOpen(on ? -1 : at)}>{section.title}<span aria-hidden="true">{on ? "−" : "+"}</span></button></h3>
      <AnimatePresence initial={false}>{on && <motion.div key="panel" id={`${uid}-p${at}`} role="region" aria-labelledby={`${uid}-h${at}`} className={styles.sectionBody} initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={reduced ? { duration: 0 } : motionTokens.spring.smooth}><div className={styles.sectionInner}>{section.content}</div></motion.div>}</AnimatePresence>
    </div>;
  })}</div>;
}

function Reviews({ distribution }: { distribution: Distribution }) {
  const reduced = useReducedMotionSafe();
  const total = reviewTotal(distribution), average = reviewAverage(distribution), ratios = barRatios(distribution);
  return <section className={styles.reviews} aria-label="Yorum özeti">
    <p className={styles.average}><b>{average === null ? "—" : <AnimatedCounter value={average} decimals={1} />}</b><span>{reviewCountText(total)}</span></p>
    <ul className={styles.bars}>{distribution.map((count, at) => <li key={at} aria-label={barRowLabel(5 - at, count)}>
      <span aria-hidden="true">{5 - at}★</span>
      <span className={styles.bar} aria-hidden="true"><motion.i initial={{ scaleX: reduced ? ratios[at]! : 0 }} whileInView={{ scaleX: ratios[at]! }} viewport={{ once: true }} transition={reduced ? { duration: 0 } : { ...motionTokens.spring.smooth, delay: at * .04 }} /></span>
      <span aria-hidden="true">{count}</span>
    </li>)}</ul>
  </section>;
}

export function ProductDetail({ name, trail, summary = [], finishes, sizes, reviews, promises = [], sections = [], maxQuantity = 10, onAddToCart, onNotify, onFavoriteChange, loading = false }: ProductDetailProps) {
  const reduced = useReducedMotionSafe();
  const [finish, setFinish] = useState(finishes[0]?.value ?? "");
  const [size, setSize] = useState(() => sizes.find(item => !isSoldOut(item, finishes[0]?.value ?? ""))?.value ?? "");
  const [quantity, setQuantity] = useState(1);
  const [state, setState] = useState<"idle" | "busy" | "done" | "error">("idle");
  const [favorite, setFavorite] = useState(false);
  const [live, announce] = useAnnouncer();
  const current = finishes.find(item => item.value === finish) ?? finishes[0];
  const picked = sizes.find(item => item.value === size);
  const soldOut = !!picked && isSoldOut(picked, finish);
  const selection: Selection = { finish, size, quantity };

  const chooseFinish = (value: string) => { setFinish(value); setSize(keepSize(sizes, size, value)); setState("idle"); };
  const add = async () => {
    if (state === "busy" || !picked) return;
    setState("busy");
    try { await onAddToCart(selection); setState("done"); announce(`${name} sepete eklendi.`); window.setTimeout(() => setState("idle"), 2200); }
    catch { setState("error"); announce("Sepete eklenemedi. Tekrar deneyebilirsiniz."); }
  };

  if (loading || !current) return <div className={styles.root} aria-busy="true" role="status" aria-label="Ürün yükleniyor"><div className={styles.layout}><span className={styles.skeletonBlock} /><div className={styles.skeletonCol}><span /><span /><span /></div></div></div>;

  const label = state === "busy" ? "Ekleniyor" : state === "done" ? "Sepete eklendi" : state === "error" ? "Tekrar dene" : picked ? addLabel(picked.price, quantity) : "Boy seçin";
  return <div className={styles.root} data-reduced={reduced || undefined}>
    <Breadcrumb items={trail} />
    <div className={styles.layout}>
      <Gallery photos={current.photos} name={name} finishKey={current.value} />
      <div className={styles.info}>
        <div className={styles.head}>
          <h1 className={styles.name}>{name}</h1>
          <button type="button" className={styles.heart} aria-pressed={favorite} aria-label={favorite ? "Favorilerden çıkar" : "Favorilere ekle"} onClick={() => { setFavorite(!favorite); onFavoriteChange?.(!favorite); }}>
            <svg viewBox="0 0 24 24" width="22" height="22" fill={favorite ? "currentColor" : "none"} stroke="currentColor" strokeWidth="1.8" aria-hidden="true"><path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.5A4 4 0 0 1 19 10c0 5.6-7 10-7 10z" /></svg>
          </button>
        </div>
        <p className={styles.price} aria-live="polite">{picked ? <AnimatedCounter value={picked.price} decimals={picked.price % 1 ? 2 : 0} prefix="₺" /> : <span className={styles.muted}>Boy seçin</span>}</p>
        <p className={styles.ratingLine}>★ {reviewAverage(reviews) === null ? "—" : <AnimatedCounter value={reviewAverage(reviews)!} decimals={1} />} <span>({reviewCountText(reviewTotal(reviews))})</span></p>
        {summary.length > 0 && <ul className={styles.summary}>{summary.map(line => <li key={line}>{line}</li>)}</ul>}
        <div className={styles.group}><p className={styles.groupLabel}>Kaplama: <b>{current.label}</b></p>
          <SwatchGroup label="Kaplama" mode="single" options={finishes.map(item => ({ value: item.value, label: item.label, color: item.color }))} value={[finish]} onToggle={chooseFinish} /></div>
        <div className={styles.group} role="radiogroup" aria-label="Boy"><p className={styles.groupLabel}>Boy</p>
          <div className={styles.sizes}>{sizes.map(item => { const out = isSoldOut(item, finish); return <button key={item.value} type="button" role="radio" aria-checked={item.value === size} className={styles.sizeOption} data-out={out || undefined} onClick={() => { setSize(item.value); setState("idle"); }}>{sizeLabel(item, out)}</button>; })}</div></div>
        <div className={styles.buy}>
          <NumberStepper label="Adet" value={quantity} min={1} max={maxQuantity} onChange={setQuantity} />
          {soldOut ? <Button variant="secondary" onClick={() => { onNotify?.(selection); announce("Gelince haber vereceğiz."); }}>Gelince haber ver</Button>
            : <Button variant="primary" className={styles.add} loading={state === "busy"} disabled={!picked} aria-busy={state === "busy"} onClick={add}>{label}</Button>}
        </div>
        {promises.length > 0 && <ul className={styles.promises}>{promises.map(item => <li key={item.title}><b>{item.title}</b><span>{item.text}</span></li>)}</ul>}
        <Reviews distribution={reviews} />
        {sections.length > 0 && <Accordion sections={sections} />}
      </div>
    </div>
    {live}
  </div>;
}

export default ProductDetail;
